from h34 import *
M=mcq;F=tf;S=short;N=num
b='<rect width="720" height="230" fill="#fbf6ea"/>'
steps=[("1. Collect","flowers, leaves, bark,","roots: beetroot, hibiscus,","marigold","#f4c7d0"),("2. Boil","in 1 to 2 litres of water","for 30 to 60 minutes,","cover with a plate","#f7d8a8"),("3. Strain","remove the plant parts,","keep the coloured liquid","= the natural dye","#d9e8b5"),("4. Dye","soak a light cloth","overnight, squeeze,","dry next morning","#c9def2")]
for i,(t,a,c,d,col) in enumerate(steps):
    x=20+i*175
    b+=f'<rect x="{x}" y="50" width="160" height="130" rx="14" fill="{col}" stroke="#8a6d3b" stroke-width="2"/><text x="{x+80}" y="80" text-anchor="middle" font-size="17" font-weight="bold">{t}</text><text x="{x+80}" y="108" text-anchor="middle" font-size="12">{a}</text><text x="{x+80}" y="126" text-anchor="middle" font-size="12">{c}</text><text x="{x+80}" y="144" text-anchor="middle" font-size="12">{d}</text>'
    if i<3: b+=f'<polygon points="{x+163},115 {x+175},115 {x+169},108" fill="#8a6d3b" opacity="0"/><text x="{x+167}" y="120" font-size="22" text-anchor="middle">→</text>'
b+='<text x="360" y="28" text-anchor="middle" font-size="18" font-weight="bold">Making a natural dye (ask an elder to help)</text>'
svgfile('c4evs-grow-dye.svg',720,230,b)
chapter(4,'evs','growing-up-with-nature','Growing up with Nature',
 ('A journey through a forest','Reena and Amit are going to their village near a forest for a harvest festival, and this year the village is becoming fully solar-powered. As they walk in, they see a tree with bright orange-red flowers, houses made of natural materials and their grandmother painting with colours from plants. They learn how people have lived with nature for a long time, from medicines to paints to festivals. Come, see how nature and culture are connected.'),
 [('The flame of the forest',['As they entered the village the children saw trees full of bright orange-red flowers.','Their father said it was the Palash tree, and when it blooms the entire forest looks reddish-orange from far away, so it is called the flame of the forest.','The same flower can have different local names, for example Palash is called Kesuda in Gujarat.','You can find five colourful flowers in your area and write their local names.','The village was also going to be fully solar-powered, which means solar panels make electricity for fans and bulbs from the Sun\'s light.']),
  ('Houses from natural materials',['Amit noticed that the village houses looked different from city houses and had beautiful decorations on the walls.','His mother said the houses are made using clay, hay, cow dung and other natural materials.','A painting on the wall was by his grandmother, who used a dye made by mixing rice flour and water.','You can make a model of a house using clay, wooden sticks, hay, grass and leaves, and decorate it with an art form you like.']),
  ('Natural colours and Gond art',['Grandmother was painting on a cloth, and she told them the paint was made from natural extracts of flowers, leaves and powdered coloured stones.','Gond art is a form of painting on walls with natural colours, and the artists draw trees, animals, birds and humans.','To make a natural dye, collect flowers, leaves, bark or roots with colour, like beetroot, hibiscus and marigold.','Boil them in one to two litres of water for thirty minutes to an hour with a plate over the container, with an elder\'s help.','Strain the liquid to remove the plant parts, and what is left is the natural dye.','Soak a light cloth in it overnight, squeeze it and dry it the next morning.']),
  ('Storing grains and respecting nature',['The children saw tools for farming and for taking honey, and earthen pots and bamboo baskets to store grains.','The earthen pots were lined inside with neem leaves, and the bamboo baskets were coated with cow dung outside, which keeps insects and pests away from the grain.','Elders know many such ways of preserving grains and vegetables, like a tumri, a round dried bottle gourd container in Uttarakhand.','The Jenu Kuruba tribe of Karnataka is named from jenu, which means honey, and they sing songs to apologise to the bees when they collect honey, which shows their respect for nature.']),
  ('Plants that heal',['Dada ji took out a mixture made with neem oil, and rubbing it on the hands and feet keeps mosquitoes away.','Reena had also made a first-aid box with medicines and mosquito repellent cream from the market.','Many plants are used as medicine, such as Tulsi, the Indian basil, whose leaves are used, and ajwain, the carom seeds.','A first-aid box should have things like bandages, antiseptic and a thermometer, and giving first aid quickly helps an injured person.','Ask elders in your family which plant parts they use and what for.']),
  ('Festivals and sacred groves',['In the evening the village was lit with colourful lights, and people wore traditional clothes and offered prayers to God and Mother Nature.','They danced to the sound of the dhol and nagada, and you can find the traditional dances and songs of your own region.','Sacred groves are small patches of forests protected by local communities, with trees and wildlife preserved there.','They are important places for the community to gather, worship and celebrate the beauty of nature.','Many festivals are linked with plants and animals, like Vat Purnima with the banyan tree, Hari Jiroti with fruit trees and the Kaziranga Elephant Festival.']),
  ('Caring for nature',['We use nature every day: fruits for food, cotton for clothes and neem for health care.','If we overuse resources there are problems, for example if we overuse wood our forests become fewer.','We can reduce paper waste, say no to plastic and spread awareness about saving plants.','We can keep food and water for birds, plant trees and organise clean-up drives.','Thinking about how to thank nature for everything we receive is the first step to protecting it.'])],
 [('Why are grains kept in neem-lined earthen pots or in bamboo baskets coated with cow dung?',[('Grains attract insects and pests.','Insects eat and spoil stored grain.'),('Neem leaves and a cow dung coating keep insects away.','These natural materials protect the grain.'),('So the grain stays safe for a long time.','This is an old way of preserving food without chemicals.')]),
  ('List four things we get from nature each day and what we use them for.',[('Fruits from trees are food.','Eating.'),('Cotton from plants makes cloth.','Clothing.'),('Neem leaves and oil are medicine and mosquito repellent.','Health care.'),('Wood from trees is used for houses and furniture, so we must not overuse it.','Overuse means fewer forests.')])],
 ('Explain how the people in Reena and Amit\'s village live in harmony with nature.',['Houses and paints made of natural materials','Neem, Tulsi and other plants used as medicine','Grains stored with neem leaves, honey collected with respect','Festivals, sacred groves and prayers to Mother Nature'],['Nature is only for us to use up','People in villages do not need plants','Natural dyes are poisonous']),
 ['The Palash tree is called the flame of the forest; plants can have different local names.','Houses, paints and storage can be made from natural materials like clay, hay and neem.','Many plants are used as medicine, like Tulsi and neem.','Sacred groves and many festivals show respect for nature.','We can care for nature by saying no to plastic, saving paper, planting trees and keeping water for birds.'],
 [M('1',1,'Why is the Palash tree called the flame of the forest?','Its orange-red flowers make the forest look reddish-orange from afar',[('It burns easily','The name is about its flower colour'),('It grows only in fire','The name is about its colour')],'When Palash blooms the forest looks reddish-orange.'),
  M('2',1,'What are the village houses in the story made of?','Clay, hay, cow dung and other natural materials',[('Only steel','The houses use natural materials'),('Glass and plastic','The houses use natural materials')],'The houses are made using clay, hay, cow dung and other natural materials.'),
  M('3',1,'What did grandmother\'s wall paint contain?','Rice flour mixed with water',[('Petrol','It is a natural dye'),('Milk and sugar','It was rice flour and water')],'She used a dye made by mixing rice flour and water.'),
  M('4',1,'What is Gond art?','Painting on walls with natural colours',[('A kind of dance','It is a form of painting'),('A farming tool','It is a form of painting')],'Gond artists draw trees, animals, birds and humans.'),
  M('5',2,'What do earthen grain pots get lined with?','Neem leaves',[('Plastic sheets','Neem leaves keep insects away'),('Sand','Neem leaves are used')],'Neem leaves protect the stored grains from insects.'),
  M('6',2,'What does the name Jenu Kuruba come from?','Jenu, which means honey',[('Jenu, a river','Jenu means honey'),('Jenu, a drum','Jenu means honey')],'They collect honey and sing songs to apologise to the bees.'),
  M('7',2,'What are Sacred Groves?','Small patches of forests protected by local communities',[('Gardens in city parks','They are patches of forest'),('Fields for farming','They are protected forest patches')],'Trees and wildlife are preserved there.'),
  M('8',2,'Which step comes right after boiling plant parts for a natural dye?','Straining the liquid',[('Soaking the cloth','Strain first, then dip the cloth'),('Collecting the flowers','That was the first step')],'Strain out the plant parts to leave the dye.'),
  M('9',2,'Which festival is linked with the banyan tree?','Vat Purnima',[('Hari Jiroti','That is linked with fruit trees'),('Kaziranga Elephant Festival','That is about elephants')],'On Vat Purnima the banyan tree is worshipped.'),
  M('10',2,'What can we do to care for nature?','Say no to plastic and plant trees',[('Cut more trees','That harms nature'),('Use more paper','That wastes resources')],'Reducing waste and planting trees protects nature.'),
  F('11',2,'The same flower can have different local names in different places.',True,'Palash is called Kesuda in Gujarat.'),
  F('12',3,'Overusing wood from forests has no effect.',False,'If we overuse wood, our forests become fewer.')],
 svgs=[('c4evs-grow-dye','Four boxes show collect, boil, strain and dye steps for making a natural dye.','The steps for making a natural dye from plant parts.')],
 keep=['Palash','Gond art','neem'])
